// ILLUSTRATIVE ONLY — runs in Jest/Vitest, not in this sandbox.
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import Counter from './Counter';

test('increments the count when the button is clicked', async () => {
  render(<Counter />);

  // Query the way a user perceives the UI.
  expect(screen.getByText('Count: 0')).toBeInTheDocument();
  const button = screen.getByRole('button', { name: /increment/i });

  // Act with realistic user interaction.
  await userEvent.click(button);

  // Assert on observable output, not internal state.
  expect(screen.getByText('Count: 1')).toBeInTheDocument();
});

test('reveals the status message after three clicks', async () => {
  render(<Counter />);
  const button = screen.getByRole('button', { name: /increment/i });

  // queryBy returns null when absent — good for asserting it is NOT there yet.
  expect(screen.queryByRole('status')).not.toBeInTheDocument();

  await userEvent.click(button);
  await userEvent.click(button);
  await userEvent.click(button);

  expect(screen.getByRole('status')).toHaveTextContent(/reached three/i);
});

