import { render, screen, waitFor } from '@testing-library/react';
import UserList from './UserList';

beforeEach(() => {
  // Replace the global fetch with a deterministic fake.
  global.fetch = jest.fn().mockResolvedValue({
    ok: true,
    json: async () => [{ id: 1, name: 'Ada' }, { id: 2, name: 'Lin' }],
  }) as unknown as typeof fetch;
});

afterEach(() => {
  jest.restoreAllMocks();
});

test('shows a loading state, then renders fetched users', async () => {
  render(<UserList />);

  // Loading appears synchronously on first render.
  expect(screen.getByText(/loading/i)).toBeInTheDocument();

  // findBy* returns a promise and retries until the element appears.
  expect(await screen.findByText('Ada')).toBeInTheDocument();
  expect(screen.getByText('Lin')).toBeInTheDocument();

  // The loading text is gone once data resolves.
  await waitFor(() => {
    expect(screen.queryByText(/loading/i)).not.toBeInTheDocument();
  });
});

