// --- Runnable component under test (plain React) ---
function App() {
  const [q, setQ] = useState('');
  const onSearch = (query) => alert('searching: ' + query);
  const submit = (e) => {
    e.preventDefault();
    if (q.trim() !== '') onSearch(q.trim());
  };
  return (
    <form onSubmit={submit} style={{ fontFamily: 'system-ui', padding: 16 }}>
      <label htmlFor="q">Search</label>
      <input id="q" value={q} onChange={(e) => setQ(e.target.value)} />
      <button type="submit">Go</button>
    </form>
  );
}

